 const normalized=m=>({...m,year:String(m.release_date||'').slice(0,4),genre:m.genres||'',runtime:`${m.runtime_minutes} min`,description:m.synopsis,poster:m.poster_path||imgFallback,backdrop:m.poster_path||imgFallback,cast:Array.isArray(m.cast)?m.cast.map(c=>typeof c==='string'?c:`${c.name}${c.role?' as '+c.role:''}`):[],hasVideo:Boolean(m.has_video||m.video_path)});
 return <Shell admin><Stack direction="row" justifyContent="space-between" alignItems="center" mb={3} flexWrap="wrap" gap={2}><div><Typography variant="overline" color="primary">CONTENT OPERATIONS</Typography><Typography variant="h3" fontWeight={800}>Movie library</Typography><Typography color="text.secondary">Changes save directly to the moviestream database.</Typography></div><Button variant="contained" startIcon={<Add/>} onClick={startAdd}>Add movie</Button></Stack><TextField size="small" placeholder="Search title or synopsis" value={query} onChange={e=>{setLoading(true);setQuery(e.target.value)}} sx={{mb:2,width:{xs:'100%',sm:340}}}/>{loading?<Typography>Loading movie records…</Typography>:items.length?<div className="admin-movie-list">{items.map(m=><Paper className="admin-movie" key={m.id}><Avatar variant="rounded" src={m.poster_path||imgFallback}/><Box flex={1} minWidth={0}><Typography fontWeight={750} noWrap>{m.title}</Typography><Typography variant="caption" color="text.secondary">{m.release_date} · {m.genres||'No genre'} · ★ {m.rating} · {m.publication_status}</Typography></Box><IconButton title="View details" onClick={()=>setViewing(normalized(m))}><Movie/></IconButton><IconButton title="Edit movie" onClick={()=>startEdit(m)}><Edit/></IconButton><IconButton title="Archive movie" onClick={()=>archive(m)}><Delete/></IconButton></Paper>)}</div>:<Empty title="No movie records yet" text="Add a movie to start building your catalog."/>}
 <Dialog open={dialog} onClose={()=>setDialog(false)} maxWidth="md" fullWidth><DialogTitle>{editing?'Update movie':'Register a movie'}</DialogTitle><form onSubmit={save}><DialogContent><div className="movie-form-grid"><TextField required label="Movie title" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/><TextField required type="date" label="Release date" InputLabelProps={{shrink:true}} value={form.releaseDate} onChange={e=>setForm({...form,releaseDate:e.target.value})}/><TextField required type="number" label="Runtime (minutes)" inputProps={{min:1,max:1000}} value={form.runtimeMinutes} onChange={e=>setForm({...form,runtimeMinutes:e.target.value})}/><TextField required type="number" label="Rating (0–10)" inputProps={{min:0,max:10,step:.1}} value={form.rating} onChange={e=>setForm({...form,rating:e.target.value})}/><TextField label="Language" value={form.language} onChange={e=>setForm({...form,language:e.target.value})}/><div className="genre-entry"><FormControl><InputLabel>Genres</InputLabel><Select multiple label="Genres" value={form.genreIds} onChange={e=>setForm({...form,genreIds:e.target.value})} renderValue={ids=>genresData.filter(g=>ids.includes(g.id)).map(g=>g.name).join(', ')}>{genresData.map(g=><MenuItem key={g.id} value={g.id}>{g.name}{g.movie_count===0?' ? new':''}</MenuItem>)}</Select></FormControl><Stack direction="row" spacing={1}><TextField size="small" fullWidth label="Add a genre for this movie" value={newGenre} onChange={e=>setNewGenre(e.target.value)} onKeyDown={e=>e.key==='Enter'&&e.preventDefault()} inputProps={{maxLength:80}}/><Button type="button" variant="outlined" onClick={createGenre}>Add</Button></Stack></div><FormControl><InputLabel>Availability</InputLabel><Select label="Availability" value={form.availability} onChange={e=>setForm({...form,availability:e.target.value})}><MenuItem value="available">Available</MenuItem><MenuItem value="unavailable">Unavailable</MenuItem></Select></FormControl><FormControl><InputLabel>Publication</InputLabel><Select label="Publication" value={form.publicationStatus} onChange={e=>setForm({...form,publicationStatus:e.target.value})}><MenuItem value="draft">Draft</MenuItem><MenuItem value="published">Published</MenuItem><MenuItem value="archived">Archived</MenuItem></Select></FormControl><TextField label="Trailer URL (optional)" value={form.trailerUrl} onChange={e=>setForm({...form,trailerUrl:e.target.value})}/><TextField label="Lead cast role (optional)" value={castRole} onChange={e=>setCastRole(e.target.value)} placeholder="Character name"/><FormControl><InputLabel>Actor</InputLabel><Select label="Actor" value={actorId} onChange={e=>setActorId(e.target.value)}><MenuItem value="">Select actor</MenuItem>{actorsData.map(a=><MenuItem key={a.id} value={a.id}>{a.name}</MenuItem>)}</Select></FormControl><TextField required multiline minRows={3} label="Synopsis" value={form.synopsis} onChange={e=>setForm({...form,synopsis:e.target.value})} className="wide-field"/><label className="file-field">Poster (JPG/PNG/WebP, max 5 MB)<input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>setPoster(e.target.files?.[0]||null)}/>{poster&&<span>{poster.name}</span>}</label><label className="file-field">Movie video (MP4/WebM, max 1 GB)<input type="file" accept="video/mp4,video/webm" onChange={e=>setVideoFile(e.target.files?.[0]||null)}/>{videoFile&&<span>{videoFile.name}</span>}</label><label className="file-field">Preview thumbnails (up to 12)<input type="file" multiple accept="image/jpeg,image/png,image/webp" onChange={e=>setThumbnails(Array.from(e.target.files||[]).slice(0,12))}/>{thumbnails.length>0&&<span>{thumbnails.length} selected</span>}</label></div></DialogContent><DialogActions><Button onClick={()=>setDialog(false)}>Cancel</Button><Button type="submit" variant="contained">{editing?'Save changes':'Create movie'}</Button></DialogActions></form></Dialog><MovieDialog movie={viewing} onClose={()=>setViewing(null)}/></Shell>
